vec3 palette(float t){

    vec3 a = vec3(0.545,0.322,0.020);
    vec3 b = vec3(0.686,0.000,0.949);
    vec3 c = vec3(0.612,0.122,0.133);
    vec3 d = vec3(0.275,0.075,0.541);
    return a+b*cos(6.28318*(c*t+d) );
}

float sdEquilateralTriangle(  in vec2 p, in float r )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p=vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}

float frack(float d){
        d = cos(d*8. +iTime)/8.; //Sin distance function, neg inside shape, outside shape positive
        d = abs(d);
        d = 0.015 /d;
        return d;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y; // Resolution ratio
    vec2 uv0=uv;
    vec3 finalColor = vec3(0.0);
    for (float i=0.0;i <  iTime*0.5; i++){ 
        uv = (fract(uv*1.5)-0.5);
        float e = length(uv) * exp(-length(uv0));
        float d = sdEquilateralTriangle(uv, 0.1);
        vec3 col = palette(length(uv0) + mod((i*0.4),0.5) + sin(iTime*0.8));        
        d = frack(d);
        e = frack(e);
        col *= e;        
        finalColor += col * mod(d,e);
        }
    fragColor = vec4(finalColor, 1.0);
}
